function JPMailBindNodeEntry:__init()
    self._data = {}
    self._surveyDojo = nil        --问卷内容
    self.handler = nil
end

function JPMailBindNodeEntry:__delete()
    self.handler = nil
    self._data = nil
    self._surveyDojo = nil        --问卷内容
end

function JPMailBindNodeEntry:Awake()
    SetButtonAction(self.BtnEntry, function()
       --跳转到绑定邮箱的界面的逻辑
        if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id277) then
            UIModule.OpenDialog({ id = Constants.UITypeIds.SettingBindEmailPopup, parameters = {cb = function(newEmail)
               --绑定成功后
                self:FillSelf() --刷新界面ui
            end}})
        end
    end)
    SetButtonAction(self.BtnReceive, function()
        ---领取按钮状态
        self:DrawRewards()
    end)
    local date = require('Frame.date')
    local now = date()
    CfUtils.WriteLocalData("BIND_EMAIL", now:fmt())
end

function JPMailBindNodeEntry:Refresh(data)
    if not data then
        return
    end
    self._data = data
    --CfUtils.FillText(self.Text , self._data.detail)
    self:FillSelf()
    self:RefreshContent()
    self:RefreshCurrencyBarInfo()
end

function JPMailBindNodeEntry:RefreshCurrencyBarInfo()
    ActivityUtils.RefreshNavigatorGoods()
end

function JPMailBindNodeEntry:FillSelf()
    --local startTime = self._data.startTime
    --local closeTime = self._data.closeTime
    --CfUtils.FillText(self.TextTitle, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    --CfUtils.FillText(self.TextTitle, self._data.name)
    local redPoint =  self.BtnReceive.transform:Find("redPoint")
    -----@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    local isBinding = 0
    if userComponent and not string.isEmpty(userComponent.userInfo.email) then
        isBinding = 1
    --    CfUtils.SetActive(redPoint, true)
    --else
    --    CfUtils.SetActive(redPoint, false)
    end
    if userComponent then
        CfUtils.SetActive(self.BtnEntry, checkNumber(userComponent.userInfo.bindTerminalRewards) == 0 and isBinding == 0)
        CfUtils.SetActive(self.BtnReceive, checkNumber(userComponent.userInfo.bindTerminalRewards) == 0 and isBinding == 1)
        CfUtils.SetActive(redPoint, checkNumber(userComponent.userInfo.bindTerminalRewards) == 0 and isBinding == 1)
