--刷新内容
function JPMailBindNodeEntry:RefreshContent()
    local goodsId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 48).num
    local goodsNum = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 49).num
    local rewards = parse_rewards(goodsId, goodsNum)
    self:FillRewards(rewards)
end

function JPMailBindNodeEntry:DrawRewards()
    GameUtils.Request("OverseaPlayer/drawBindTerminalRewards", {activityUuid = self._data.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        -----@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        userComponent.userInfo.bindTerminalRewards = 1
        ---已领取状态
        if userComponent then
            local redPoint =  self.BtnReceive.transform:Find("redPoint")
            CfUtils.SetActive(redPoint, checkNumber(userComponent.userInfo.bindTerminalRewards) == 0)
        end
        CfUtils.SetActive(self.BtnReceive, false) ---已领取的情况下
        GameUtils.SetRedPointNum(Constants.RedPointConst.OtherSettingEmailButton, -1)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OtherSettingEmailButton)
        ActivityUtils.UpdateActivityMainRedPointState(self._data.id,  -1)
        local jsonData = response.data
        if #jsonData.rewards > 0 then
            GoodsUtils.DrawRewards(jsonData.rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })     
        else 
            GameUtils.Toast(localize("奖励已领取"))
        end
        self:RefreshContent()
    end)
end

--奖励
function JPMailBindNodeEntry:FillRewards(rewards)
    if not rewards then
        return
    end
    ---@type CommonGoodsList
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, CommonGoodsListNode)
    if not scr then
        return
    end
    scr:FreshBaseUI(rewards, false)
    -----@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if userComponent and checkNumber(userComponent.userInfo.bindTerminalRewards) == 1 then
        scr:SetIsGetMaskShow(true)
    end
end

function JPMailBindNodeEntry:OnDestroy()
    self.handler = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return JPMailBindNodeEntry
